WITH filtered_employees AS (SELECT * FROM employees WHERE job_title IN ('Analyst', 'Designer') OR job_title NOT IN ('Manager', 'Designer')), EmployeesStats AS (SELECT is_remote, DATE_TRUNC('MONTH', hire_date) AS hire_month, MAX(hire_date) AS last_hire_date FROM filtered_employees GROUP BY is_remote, DATE_TRUNC('MONTH', hire_date)) SELECT is_remote, hire_month, last_hire_date FROM EmployeesStats ORDER BY hire_month DESC, last_hire_date;
